import{c as t,Q as a,j as o,m as r}from"./chunks/framework.DCQwiej8.js";const u=JSON.parse('{"title":"Targets","description":"","frontmatter":{},"headers":[],"relativePath":"pipeline/guide/targets/index.md","filePath":"pipeline/guide/targets/index.md","lastUpdated":1783588917000}'),d={name:"pipeline/guide/targets/index.md"};function c(i,e,s,n,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="targets" tabindex="-1">Targets <a class="header-anchor" href="#targets" aria-label="Permalink to &quot;Targets&quot;">​</a></h1><p>The <strong>target</strong> side of a pipeline owns the <code>PIPELINE.WRITE_BATCH</code> phase plus the pre-write clear (<code>truncate</code> / <code>deleteSlice</code>) that full-refresh and partial-refresh modes need. A target adapter reports its <code>capabilities()</code> so <code>addPipeline</code> can reject incompatible configs at registration time rather than halfway through the first run.</p><p>Every write is dispatched through the resolved target adapter. Non-<code>db</code> targets without a <code>target.adapter</code> class reference are rejected at registration — there is no silent fallback to the local DB.</p><h2 id="resolution-order" tabindex="-1">Resolution order <a class="header-anchor" href="#resolution-order" aria-label="Permalink to &quot;Resolution order&quot;">​</a></h2><p><code>addPipeline(...)</code> resolves the target adapter in this order:</p><ol><li><code>config.target.adapter</code> — class reference extending <code>BaseTargetAdapter</code>. Full control; takes precedence over <code>target.service</code>.</li><li><code>config.target.service</code> unset or <code>&#39;db&#39;</code> → built-in <code>DbTargetAdapter</code>.</li><li><code>config.target.kind</code> (<code>&#39;odata&#39; | &#39;odata-v2&#39;</code>) — explicit transport selector. Takes precedence over the connected service&#39;s auto-detected kind.</li><li>Auto-detected <code>service.options.kind</code> (<code>&#39;odata&#39; | &#39;odata-v2&#39;</code>) on the connected remote service → built-in <code>ODataTargetAdapter</code>.</li><li>Any other <code>config.target.service</code> with no <code>target.adapter</code> → <strong>registration error</strong> pointing to <a href="./custom.html">Custom target adapter</a>.</li></ol><h2 id="built-in-target-adapters" tabindex="-1">Built-in target adapters <a class="header-anchor" href="#built-in-target-adapters" aria-label="Permalink to &quot;Built-in target adapters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Adapter</th><th>Resolved when</th><th>Capabilities</th><th>Page</th></tr></thead><tbody><tr><td><code>DbTargetAdapter</code></td><td><code>target.service</code> unset or <code>&#39;db&#39;</code></td><td><code>batchInsert</code>, <code>keyAddressableUpsert</code>, <code>batchDelete</code>, <code>truncate</code></td><td><a href="./db.html">Local DB</a></td></tr><tr><td><code>ODataTargetAdapter</code></td><td><code>target.kind</code> is <code>&#39;odata&#39; / &#39;odata-v2&#39;</code>, or the connected service advertises that kind</td><td><code>batchInsert</code>, <code>keyAddressableUpsert</code>, <code>batchDelete</code>, <code>truncate</code></td><td><a href="./odata.html">OData</a></td></tr><tr><td>Any other transport</td><td>Register a <a href="./custom.html">custom target adapter</a></td><td>Whatever the adapter advertises</td><td></td></tr></tbody></table><ul><li><p><strong><a href="./db.html">Local DB</a></strong> — The default. Resolved automatically when <code>target.service</code> is unset or <code>&#39;db&#39;</code>. Writes <code>UPSERT</code> / <code>INSERT</code> / <code>DELETE</code> via CAP&#39;s <code>cds.connect.to(&#39;db&#39;)</code>.</p></li><li><p><strong><a href="./odata.html">OData</a></strong> — Forward writes to a remote OData V2 / V4 service through CAP&#39;s remote runtime — <code>UPSERT.entries(...)</code> → POST / PUT / PATCH, with <code>$batch</code> change sets where the provider supports them.</p></li><li><p><strong><a href="./custom.html">Custom target adapter</a></strong> — Extend <code>BaseTargetAdapter</code> for non-db, non-OData destinations (message buses, custom HTTP APIs, …). Worked example: a reporting service over <code>srv.send()</code>.</p></li></ul><h2 id="capability-gating" tabindex="-1">Capability gating <a class="header-anchor" href="#capability-gating" aria-label="Permalink to &quot;Capability gating&quot;">​</a></h2><p><code>addPipeline</code> rejects incompatible configs by consulting the target adapter&#39;s <code>capabilities()</code>:</p><table tabindex="0"><thead><tr><th>Config</th><th>Required capability</th></tr></thead><tbody><tr><td><code>mode: &#39;delta&#39;</code></td><td><code>keyAddressableUpsert</code></td></tr><tr><td><code>mode: &#39;full&#39;</code></td><td><code>truncate</code> <strong>or</strong> <code>batchDelete</code></td></tr><tr><td><code>source.query</code> (query-shape)</td><td><code>batchInsert</code></td></tr></tbody></table><p>Omitted keys default to <code>false</code>. Report only what your adapter actually supports — <code>addPipeline</code> rejects users at registration rather than halfway through the first run. The default <code>DbTargetAdapter</code> reports all four capabilities as <code>true</code>.</p><h2 id="transactional-semantics" tabindex="-1">Transactional semantics <a class="header-anchor" href="#transactional-semantics" aria-label="Permalink to &quot;Transactional semantics&quot;">​</a></h2><p>Query-shape (snapshot) pipelines run inside a <code>cds.tx</code> transaction — so <code>truncate</code> / <code>deleteSlice</code> + batch <code>INSERT</code>s commit atomically and a mid-run crash leaves the previous snapshot intact. Entity-shape (UPSERT) pipelines run without an outer transaction: each batch commits on its own so partial progress survives interruptions.</p><p>Target adapters do not have to manage <code>cds.tx</code> themselves; they inherit the ambient <code>cds.context</code> / transaction. Custom remote-protocol adapters (e.g. a reporting-service adapter) need to surface their own atomicity guarantees at the service boundary — <code>cds.tx</code> does not span remote HTTP calls.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../concepts/inference.html">Concepts → Inference rules</a> — target adapter selection and the full registration matrix.</li><li><a href="./../sources/">Sources</a> — the peer section covering the READ phase.</li><li><a href="./../recipes/custom-target-adapter.html">Recipes → Custom target adapter</a> — end-to-end reporting-service example.</li></ul>',18)])])}const g=t(d,[["render",c]]);export{u as __pageData,g as default};
